DROP DATABASE IF EXISTS w07_f1;
CREATE DATABASE w07_f1 CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE w07_f1;

CREATE TABLE `country` (
  `country_id` VARCHAR(64) NOT NULL,
  `alpha2_code` CHAR(2) NOT NULL,
  `alpha3_code` CHAR(3) NOT NULL,
  `name` VARCHAR(100) NOT NULL,
  `demonym` VARCHAR(100) DEFAULT NULL,
  `continent_id` VARCHAR(32) NOT NULL,
  PRIMARY KEY (`country_id`),
  UNIQUE KEY `uk_country_alpha2` (`alpha2_code`),
  UNIQUE KEY `uk_country_alpha3` (`alpha3_code`)
) ENGINE=InnoDB;

CREATE TABLE `circuit` (
  `circuit_id` VARCHAR(64) NOT NULL,
  `name` VARCHAR(100) NOT NULL,
  `full_name` VARCHAR(150) NOT NULL,
  `circuit_type` VARCHAR(20) NOT NULL,
  `direction` VARCHAR(20) NOT NULL,
  `place_name` VARCHAR(100) NOT NULL,
  `country_id` VARCHAR(64) NOT NULL,
  `latitude` DECIMAL(10,6) NOT NULL,
  `longitude` DECIMAL(10,6) NOT NULL,
  `length_km` DECIMAL(6,3) NOT NULL,
  `turns` INT NOT NULL,
  PRIMARY KEY (`circuit_id`),
  KEY `idx_circuit_country` (`country_id`),
  CONSTRAINT `fk_circuit_country` FOREIGN KEY (`country_id`) REFERENCES `country` (`country_id`)
) ENGINE=InnoDB;

CREATE TABLE `constructor` (
  `constructor_id` VARCHAR(64) NOT NULL,
  `name` VARCHAR(100) NOT NULL,
  `full_name` VARCHAR(150) NOT NULL,
  `country_id` VARCHAR(64) NOT NULL,
  `total_championship_wins` INT NOT NULL DEFAULT 0,
  `total_race_entries` INT NOT NULL DEFAULT 0,
  `total_race_wins` INT NOT NULL DEFAULT 0,
  `total_podiums` INT NOT NULL DEFAULT 0,
  PRIMARY KEY (`constructor_id`),
  KEY `idx_constructor_country` (`country_id`),
  CONSTRAINT `fk_constructor_country` FOREIGN KEY (`country_id`) REFERENCES `country` (`country_id`)
) ENGINE=InnoDB;

CREATE TABLE `driver` (
  `driver_id` VARCHAR(64) NOT NULL,
  `name` VARCHAR(100) NOT NULL,
  `first_name` VARCHAR(64) NOT NULL,
  `last_name` VARCHAR(64) NOT NULL,
  `abbreviation` CHAR(3) NOT NULL,
  `permanent_number` INT DEFAULT NULL,
  `gender` VARCHAR(16) NOT NULL,
  `date_of_birth` DATE NOT NULL,
  `place_of_birth` VARCHAR(100) DEFAULT NULL,
  `birth_country_id` VARCHAR(64) NOT NULL,
  `nationality_country_id` VARCHAR(64) NOT NULL,
  `total_championship_wins` INT NOT NULL DEFAULT 0,
  `total_race_starts` INT NOT NULL DEFAULT 0,
  `total_race_wins` INT NOT NULL DEFAULT 0,
  `total_podiums` INT NOT NULL DEFAULT 0,
  PRIMARY KEY (`driver_id`),
  KEY `idx_driver_birth_country` (`birth_country_id`),
  KEY `idx_driver_nationality` (`nationality_country_id`),
  CONSTRAINT `fk_driver_birth_country` FOREIGN KEY (`birth_country_id`) REFERENCES `country` (`country_id`),
  CONSTRAINT `fk_driver_nationality` FOREIGN KEY (`nationality_country_id`) REFERENCES `country` (`country_id`)
) ENGINE=InnoDB;

CREATE TABLE `race` (
  `race_id` INT NOT NULL,
  `season_year` INT NOT NULL,
  `round_number` INT NOT NULL,
  `race_date` DATE NOT NULL,
  `official_name` VARCHAR(160) NOT NULL,
  `qualifying_format` VARCHAR(32) NOT NULL,
  `circuit_id` VARCHAR(64) NOT NULL,
  `course_length_km` DECIMAL(6,3) NOT NULL,
  `turns` INT NOT NULL,
  `laps` INT NOT NULL,
  `distance_km` DECIMAL(8,3) NOT NULL,
  PRIMARY KEY (`race_id`),
  UNIQUE KEY `uk_race_season_round` (`season_year`, `round_number`),
  KEY `idx_race_circuit` (`circuit_id`),
  CONSTRAINT `fk_race_circuit` FOREIGN KEY (`circuit_id`) REFERENCES `circuit` (`circuit_id`)
) ENGINE=InnoDB;

CREATE TABLE `race_result` (
  `race_id` INT NOT NULL,
  `position_display_order` INT NOT NULL,
  `position_number` INT DEFAULT NULL,
  `position_text` VARCHAR(16) NOT NULL,
  `driver_number` VARCHAR(10) NOT NULL,
  `driver_id` VARCHAR(64) NOT NULL,
  `constructor_id` VARCHAR(64) NOT NULL,
  `laps` INT DEFAULT NULL,
  `finish_time` VARCHAR(32) DEFAULT NULL,
  `time_millis` BIGINT DEFAULT NULL,
  `gap` VARCHAR(32) DEFAULT NULL,
  `reason_retired` VARCHAR(120) DEFAULT NULL,
  `points` DECIMAL(5,2) NOT NULL DEFAULT 0.00,
  `pole_position` TINYINT(1) NOT NULL DEFAULT 0,
  `grid_position_number` INT DEFAULT NULL,
  `positions_gained` INT DEFAULT NULL,
  `pit_stops` INT DEFAULT NULL,
  `fastest_lap` TINYINT(1) NOT NULL DEFAULT 0,
  `driver_of_the_day` TINYINT(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`race_id`, `position_display_order`),
  UNIQUE KEY `uk_race_result_driver` (`race_id`, `driver_id`),
  KEY `idx_rr_driver` (`driver_id`),
  KEY `idx_rr_constructor` (`constructor_id`),
  CONSTRAINT `fk_rr_race` FOREIGN KEY (`race_id`) REFERENCES `race` (`race_id`),
  CONSTRAINT `fk_rr_driver` FOREIGN KEY (`driver_id`) REFERENCES `driver` (`driver_id`),
  CONSTRAINT `fk_rr_constructor` FOREIGN KEY (`constructor_id`) REFERENCES `constructor` (`constructor_id`)
) ENGINE=InnoDB;

CREATE TABLE `qualifying_result` (
  `race_id` INT NOT NULL,
  `position_display_order` INT NOT NULL,
  `position_number` INT DEFAULT NULL,
  `position_text` VARCHAR(16) NOT NULL,
  `driver_number` VARCHAR(10) NOT NULL,
  `driver_id` VARCHAR(64) NOT NULL,
  `constructor_id` VARCHAR(64) NOT NULL,
  `q1_time` VARCHAR(32) DEFAULT NULL,
  `q1_millis` INT DEFAULT NULL,
  `q2_time` VARCHAR(32) DEFAULT NULL,
  `q2_millis` INT DEFAULT NULL,
  `q3_time` VARCHAR(32) DEFAULT NULL,
  `q3_millis` INT DEFAULT NULL,
  `laps` INT DEFAULT NULL,
  PRIMARY KEY (`race_id`, `position_display_order`),
  UNIQUE KEY `uk_qualifying_result_driver` (`race_id`, `driver_id`),
  KEY `idx_qr_driver` (`driver_id`),
  KEY `idx_qr_constructor` (`constructor_id`),
  CONSTRAINT `fk_qr_race` FOREIGN KEY (`race_id`) REFERENCES `race` (`race_id`),
  CONSTRAINT `fk_qr_driver` FOREIGN KEY (`driver_id`) REFERENCES `driver` (`driver_id`),
  CONSTRAINT `fk_qr_constructor` FOREIGN KEY (`constructor_id`) REFERENCES `constructor` (`constructor_id`)
) ENGINE=InnoDB;


























